STORY = [('mariarosa', 'Mi amor, no pasa nada, tienes aquí un futuro muy bonito. Te lo prometo.', "My love, it's alright, you have a lovely future right here. I promise you.", [(130, 'mi amor, que no pasa nada, que tienes aquí un futuro muy bonito'), (131, 'te lo prometo')], ''), ('belinda', 'Pues vamos a ver ese futuro. ¿Qué pasa con el trabajo?', "Well let's see that future. What about work?", [(132, 'Pues vamos a ver ese futuro'), (134, 'el trabajo')], ''), ('mariarosa', 'La carta del sol. Esto te va a dar felicidad con gente maravillosa.', 'The Sun card. This is going to bring you happiness with wonderful people.', [(141, 'la carta del sol'), (142, 'Esto te va a dar felicidad'), (143, 'con gente maravillosa')], ''), ('belinda', '¿En serio? ¿Tele?', 'Really? Television?', [(142, '¿En serio?'), (144, '¿Tele?')], ''), ('mariarosa', 'Tele de momento no. Teatro, musical, cabaret.', 'Not television for now. Theatre, musicals, cabaret.', [(144, 'Tele de momento no'), (145, 'teatro, musical, cabaret')], ''), ('belinda', 'Pues he montado una banda. ¡Estoy supercontenta!', "Well, I've put together a band. I'm super happy!", [(146, 'Pues he montado una banda'), (150, 'Estoy supercontenta')], ''), ('mariarosa', 'Mira, la carta de la estrella, la carta de la fama y del triunfo.', 'Look, the Star card, the card of fame and triumph.', [(147, 'Mira, la carta de la estrella'), (148, 'la carta de la fama, del triunfo')], ''), ('paquita', 'A ver, para que nos organicemos bien y no haya líos, lo haremos por orden alfabético.', "Alright, so we stay organised and avoid arguments, we'll go in alphabetical order.", [(156, 'A ver, para que nos organicemos bien y no haya líos'), (157, 'Lo haremos por orden alfabético')], ''), ('paquita', 'Tranquilitos todos. Nos atenderán a todos. Un poco de silencio, que se va la magia.', 'Calm down, everyone. Everyone will be seen. A little quiet, or the magic will fade.', [(160, 'Tranquilitos todos. Nos atenderán a todos'), (165, 'un poco de silencio, que se va la magia')], ''), ('paquita', '¿Sabes qué debes enseñarme? El vestido de los Goya, que me explotaba.', 'Do you know what you need to show me? My Goya dress, because it was bursting on me.', [(162, '¿Sabes qué debes enseñarme? El vestido de los Goya'), (163, 'Me explotaba')], ''), ('paquita', 'Venga, Belinda, cariño. Llevas aquí tres horas y tenemos mucha plancha.', "Come on, Belinda, darling. You've been here three hours and we have a lot of work waiting.", [(168, 'Venga, Belinda, cariño. Llevas aquí tres horas'), (169, 'Tenemos mucha plancha')], ''), ('belinda', 'Sí, ya voy. ¿Vendrás al concierto benéfico el viernes?', "Yes, I'm coming. Will you come to the charity concert on Friday?", [(169, 'Sí, ya voy'), (170, '¿Vendrás al concierto el viernes?'), (171, 'El concierto benéfico')], ''), ('paquita', 'Cariño, ¿cómo voy a ir si tenemos lo de los Goya y está la niña nominada?', 'Darling, how can I go when we have the Goyas and my girl is nominated?', [(173, 'Cariño, ¿cómo voy a ir si tenemos lo de los Goya'), (174, 'está la niña nominada')], ''), ('belinda', 'Siempre estás ocupada, Paquita.', "You're always busy, Paquita.", [(179, 'Siempre estás ocupada, Paquita')], '')]
